package com.vibeguard.samples.recovery; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import java.util.concurrent.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/recovery") public class RecoveryController {private final Map<String,String> tokens=new ConcurrentHashMap<>();@PostMapping("/request") public ResponseEntity<Map<String,String>> request(@Valid @RequestBody Request request){String token=UUID.randomUUID().toString();tokens.put(token,request.email());return ResponseEntity.ok(Map.of("recoveryToken",token));}@PostMapping("/complete") public ResponseEntity<Void> complete(@Valid @RequestBody Complete complete){return tokens.remove(complete.token())==null?ResponseEntity.badRequest().build():ResponseEntity.noContent().build();}record Request(@Email String email){}record Complete(@NotBlank String token,@NotBlank String newCredential){} }
